//! Oracle tier: reads artifacts regenerated by `scripts/regen-fixtures.py`
//! (tools/fixtures/langlibelk-language-{public,url}.toml, docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
use d2_rs_core::{Size, ast::Shared};
use d2_rs_language::{ParseOptions, compiler, parse};
use serde_json::Value;
use std::collections::HashMap;
fn bytes(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}
struct Unmeasured;
impl compiler::GraphMeasurer for Unmeasured {
    fn measure(&self, _: &str) -> Size {
        Size::default()
    }
}
#[test]
fn original_graph_compiler_preserves_class_application_diagnostics() {
    let fixture: Value = serde_json::from_str(d2_rs_testdata::oracle_fixture!(
        "tests/fixtures/public-class-applications-v090.json"
    ))
    .unwrap();
    assert_eq!(fixture["requests"].as_array().unwrap().len(), 110);
    for (request, source) in fixture["requests"]
        .as_array()
        .unwrap()
        .iter()
        .zip(fixture["source"].as_array().unwrap())
    {
        let utf16 = request["utf16"].as_bool().unwrap();
        let parsed = parse(
            request["path"].as_str().unwrap(),
            &bytes(request["hex"].as_str().unwrap()),
            Some(ParseOptions {
                utf16_positions: utf16,
                errors: None,
            }),
        );
        assert!(parsed.error.is_none());
        let files = request["files_hex"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(k, v)| (k.clone(), bytes(v.as_str().unwrap())))
            .collect::<HashMap<_, _>>();
        let (c, root) = compiler::compile_ir_with_options(
            Shared::new(parsed.map),
            compiler::CompileOptions {
                utf16_positions: utf16,
                import_opener: Some(Box::new(move |path| {
                    files
                        .get(path)
                        .map(|b| {
                            Box::new(std::io::Cursor::new(b.clone()))
                                as Box<dyn d2_rs_language::stream::ByteReader>
                        })
                        .ok_or_else(|| format!("open {path}: file does not exist"))
                })),
            },
        )
        .unwrap();
        let result = compiler::lower_graph_with_measurer_and_labels(&c, root, &Unmeasured);
        let error = result.as_ref().err().map(|error| error.to_string());
        assert_eq!(error.as_deref(), source["error"].as_str(), "{request}");
        if let Ok((graph, labels, styles)) = result {
            for object in source["graph"]["objects"].as_array().into_iter().flatten() {
                let id = graph
                    .nodes
                    .iter()
                    .position(|node| Some(node.external_id.as_str()) == object["AbsID"].as_str())
                    .unwrap();
                let node_id = d2_rs_core::NodeId(u32::try_from(id).unwrap());
                let expected_shape = match object["attributes"]["shape"]["value"].as_str().unwrap()
                {
                    "rectangle" => d2_rs_core::ShapeKind::Rectangle,
                    "circle" => d2_rs_core::ShapeKind::Circle,
                    "square" => d2_rs_core::ShapeKind::RealSquare,
                    "text" => d2_rs_core::ShapeKind::Text,
                    "code" => d2_rs_core::ShapeKind::Code,
                    shape => panic!("unexpected source shape {shape}"),
                };
                assert_eq!(graph.nodes[id].shape, expected_shape, "{request}");
                assert_eq!(
                    labels.get(&node_id).map(String::as_str),
                    object["attributes"]["label"]["value"].as_str(),
                    "{request}"
                );
                let style = serde_json::to_value(styles.get(&node_id).unwrap()).unwrap();
                assert_eq!(
                    style["language"].as_str(),
                    object["attributes"]["language"].as_str(),
                    "{request} language"
                );
                for (go, rust) in [
                    ("stroke", "stroke"),
                    ("fill", "fill"),
                    ("opacity", "opacity"),
                    ("strokeWidth", "stroke_width"),
                    ("fontColor", "font_color"),
                ] {
                    assert_eq!(
                        style[rust].as_str(),
                        object["attributes"]["style"][go]["value"].as_str(),
                        "{request} {rust}"
                    );
                }
            }
            for (id, edge) in source["graph"]["edges"]
                .as_array()
                .into_iter()
                .flatten()
                .enumerate()
            {
                let style = serde_json::to_value(&graph.edge_styles[id]).unwrap();
                assert_eq!(
                    style["language"].as_str(),
                    edge["attributes"]["language"].as_str(),
                    "{request} language"
                );
                assert_eq!(
                    graph.edge_links[id].as_deref(),
                    edge["attributes"]["link"]["value"].as_str(),
                    "{request} edge link"
                );
                assert_eq!(
                    graph.edge_tooltips[id].as_deref(),
                    edge["attributes"]["tooltip"]["value"].as_str(),
                    "{request} edge tooltip"
                );
                assert_eq!(
                    graph.edge_labels[id]
                        .as_ref()
                        .map(|label| label.text.as_str())
                        .unwrap_or(""),
                    edge["attributes"]["label"]["value"].as_str().unwrap(),
                    "{request} edge label"
                );
                for (go, rust) in [
                    ("stroke", "stroke"),
                    ("fill", "fill"),
                    ("opacity", "opacity"),
                    ("strokeWidth", "stroke_width"),
                    ("fontColor", "font_color"),
                ] {
                    assert_eq!(
                        style[rust].as_str(),
                        edge["attributes"]["style"][go]["value"].as_str(),
                        "{request} {rust}"
                    );
                }
            }
        }
    }
}
